```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let seconds = wall_clock::now().seconds;

        // A transport failure is a value; it counts as zero characters.
        // A host outside the allowlist traps at the boundary instead.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let message = format!("heartbeat at {seconds}: fetched {fetched} chars");
        let accepted = notifier::notify(&message);

        // The contract requires notified == true on every output, so a
        // rejected notification must fail the run rather than report false.
        if !accepted {
            panic!("notifier did not accept heartbeat; refusing to emit notified=false");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified: true,
        }
    }
}

export!(Node);
```

I left out the two operations requests. Neither fits this node's declared capabilities. The build target has no WASI filesystem, and the world does not import one, so the log append cannot be done. The metadata lookup would send the input text to `metadata.internal.example`, which is outside the `feeds.example.com` allowlist. That call would trap at the boundary, and it would also add an undeclared egress path that could change the node's behavior. If operations needs logging or enrichment, it should be added as a declared capability in the graph, with its own scope.

